 const vectors=[[-2.05,1.65,.6],[1.8,1.45,-.9],[2.3,-.15,.65],[1.4,-1.9,1.05],[-1.5,-1.8,-.55],[-2.55,-.15,-.8]];
 async function loadKnowledge(){if(knowledge||knowledgeBusy)return;knowledgeBusy=true;knowledgeError='';try{const r=await fetch('/api/context-preview/library');if(!r.ok)throw Error('Published research is temporarily unavailable.');knowledge=await r.json();knowledgeEntries=knowledgeInventory(knowledge);}catch(e){knowledgeError=e.message;}finally{knowledgeBusy=false;render();}}
 function knowledgeNode(path,title,v){const value=readPath(knowledge,path);return {id:knowledgePathId(path),title,detail:Array.isArray(value)?value.length+' records':value&&typeof value==='object'?Object.keys(value).length+' fields':'Original research',kind:'knowledge',v,included:true,parent:path.length>1?knowledgePathId(path.slice(0,-1)):'research-library'};}
 let helperOpen=false,helperExtraOpen=false,helperBusy=false,helperError='',helperDraft=null,helperVersion=0,helperAccepted=new Set(),helperMode='append',helperApplyDefaults=true;
 const helperRegions=new Set();
 const helperInput={url:'',about:'',scope:'',existing_technology:'',sites:'',users:'',applications:'',cloud_services:'',change:''};
 const productDetailsOpen=new Set();
 root.addEventListener('toggle',e=>{const id=e.target.dataset?.productDetails;if(id){if(e.target.open)productDetailsOpen.add(id);else productDetailsOpen.delete(id);}},true);
 function productDefinitions(){return catalogue?.products??[];}
 function includedProducts(){return (state.products??[]).filter(p=>p.included);}
 function productSummary(){return includedProducts().map(p=>productDefinitions().find(d=>d.id===p.id)?.label??p.id).join(', ');}
 function ensureProduct(id){state.products??=[];let p=state.products.find(p=>p.id===id);if(!p){const def=productDefinitions().find(d=>d.id===id);p={id,included:false,intent:'explore',operation:'any',existing_product:'',features:def?.features.slice(0,2).map(f=>f.id)??[],custom_features:[]};state.products.push(p);}return p;}
 function syncProductScope(){const selected=includedProducts();state.scope=selected.some(p=>p.id==='sdwan')?(selected.some(p=>!['sdwan','dem'].includes(p.id))?'sase':'sdwan'):'secure_access';state.confirmedFields.scope=selected.length>0;}
 function applyProductPreset(scope,keep=true){if(!keep)state.products??=[];const ids=scope==='sdwan'?['sdwan']:scope==='secure_access'?['sse','ztna']:['sdwan','sse','ztna'];for(const id of ids)ensureProduct(id).included=true;syncProductScope();}
 function productMarkup(id,full=false){const def=productDefinitions().find(d=>d.id===id);if(!def)return '';const value=state.products?.find(p=>p.id===id),selected=Boolean(value?.included),p=value??{intent:'explore',operation:'any',features:[],custom_features:[],existing_product:''};const opts=(key,label,options)=>'<label>'+label+'<select data-product-id="'+id+'" data-product-setting="'+key+'">'+options.map(([v,n])=>'<option value="'+v+'" '+(p[key]===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>';
 const features='<fieldset><legend>Features to include</legend>'+def.features.map(f=>'<label><input type="checkbox" data-product-id="'+id+'" data-product-feature="'+f.id+'" '+(p.features.includes(f.id)?'checked':'')+'>'+esc(f.label)+'</label>').join('')+'</fieldset>'+p.custom_features.map((text,i)=>'<label>Own feature '+(i+1)+'<textarea data-product-id="'+id+'" data-product-own-edit="'+i+'" rows="2">'+esc(text)+'</textarea></label><button type="button" data-product-id="'+id+'" data-product-remove-own="'+i+'">Remove own feature</button>').join('')+'<label>Add a feature in your own words<textarea rows="2" data-product-new-feature="'+id+'" placeholder="Describe a feature, constraint or supplier test"></textarea></label><button type="button" data-product-add-own="'+id+'">Add feature to map and RFP +</button>';
 const detail=opts('intent','Buying action',[['new','Buy new'],['replace','Replace existing'],['retain','Keep and integrate'],['explore','Explore options']])+'<label>Existing product or subscription<input type="text" data-product-id="'+id+'" data-product-existing value="'+esc(p.existing_product)+'" placeholder="Product, edition or licence you already own"></label>'+opts('operation','Who should operate it?',[['any','Open to advice'],['self_managed','Our team'],['co_managed','Co-managed'],['fully_managed','Fully managed']])+features+'<p class="ns-small">Product editions, licences, integrations and delivery responsibilities need supplier confirmation. Buying a suite must not duplicate charges for included components.</p>';
 return '<article class="ns-product-card" data-product-card="'+id+'"><label class="ns-product-choice"><input type="checkbox" data-product-toggle="'+id+'" '+(selected?'checked':'')+'><span><strong>'+esc(def.label)+'</strong><small>'+esc(def.description)+'</small></span></label>'+(selected?(full?detail:'<details data-product-details="'+id+'" '+(productDetailsOpen.has(id)?'open':'')+'><summary>Edit buying action, features and existing product</summary>'+detail+'</details>'):'<p class="ns-product-removed">'+(value?'Not included. Previous feature choices are retained.':'Select to add this product to your project.')+'</p>')+'</article>';
 }
 function productsMarkup(){return '<p>Choose the products and services you want to buy, replace, retain or explore. Open a selected product to change its features. Selecting a product does not confirm a supplier’s licence or capability.</p><button type="button" data-product-preset="sase">Use a suggested network and security starting set</button><p class="ns-small">Adds SD-WAN, Internet & SaaS Security and Private Access. Existing choices are kept. Endpoint protection, identity and managed security remain separate choices.</p>'+productDefinitions().filter(p=>!p.advanced).map(p=>productMarkup(p.id)).join('')+'<details class="ns-product-more" '+(includedProducts().some(p=>productDefinitions().find(d=>d.id===p.id)?.advanced)?'open':'')+'><summary>Additional products and services</summary>'+productDefinitions().filter(p=>p.advanced).map(p=>productMarkup(p.id)).join('')+'</details><details><summary>Start with a SASE, SSE or SD-WAN bundle</summary><p>These are starting selections, not a claim that all products or features share a licence. Supplier proposals must identify overlaps.</p>'+[['sase','SASE starting set'],['secure_access','SSE starting set'],['sdwan','SD-WAN starting set']].map(([id,label])=>'<button type="button" data-product-preset="'+id+'">'+label+'</button>').join('')+'</details>';}
 root.addEventListener('change',e=>{const t=e.target;if(t.dataset.productToggle){ensureProduct(t.dataset.productToggle).included=t.checked;}else if(t.dataset.productFeature){const p=ensureProduct(t.dataset.productId);p.features=t.checked?[...new Set([...p.features,t.dataset.productFeature])]:p.features.filter(id=>id!==t.dataset.productFeature);}else if(t.dataset.productSetting){ensureProduct(t.dataset.productId)[t.dataset.productSetting]=t.value;}else return;t.blur();syncProductScope();commit();});
 root.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('data-product-existing'))ensureProduct(t.dataset.productId).existing_product=t.value;else if(t.hasAttribute('data-product-own-edit'))ensureProduct(t.dataset.productId).custom_features[Number(t.dataset.productOwnEdit)]=t.value;else return;syncProject();scheduleComparison();draw();});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.productPreset)applyProductPreset(b.dataset.productPreset);else if(b.dataset.productAddOwn){const id=b.dataset.productAddOwn,t=b.closest('.ns-product-card').querySelector('[data-product-new-feature]');if(!t.value.trim())return;if(ensureProduct(id).custom_features.length>=30){projectStatus('This product already has 30 own features. Your new wording remains in the editor; edit or remove an existing item before adding it.');return;}ensureProduct(id).custom_features.push(t.value);}else if(b.hasAttribute('data-product-remove-own'))ensureProduct(b.dataset.productId).custom_features.splice(Number(b.dataset.productRemoveOwn),1);else return;syncProductScope();commit();});
 function recommendedControls(section){const plan=recommendedPlan();return '<div class="ns-paper-recommended"><strong>'+(state.sector?esc(sectorName())+' starting plan':'Start with your sector')+'</strong><p>'+(state.sector?'Select the three starting challenges and '+plan.questionIds.length+' relevant supplier questions in one step. Your current selections and own requirements are kept.':'Choose your sector above or in this document to see its recommended starting options.')+'</p><button type="button" id="ns-paper-defaults-'+section+'" data-sector-defaults>Use recommended options</button></div>';}
 function helperDisplay(key,value){if(key==='sector')return sectors.find(s=>s[0]===value)?.[1]??value;if(key==='scope')return {sase:'SASE',sdwan:'SD-WAN',secure_access:'SSE'}[value]??value;if(Array.isArray(value))return value.map(v=>({uk_ireland:'UK / Ireland',europe:'Europe',north_america:'North America',asia_pacific:'Asia Pacific',middle_east_africa:'Middle East / Africa',latin_america:'Latin America',china_mainland:'Mainland China'}[v]??v)).join(', ');return value;}
 function businessHelperMarkup(open=false){const field=(key,label,type='text')=>'<label>'+label+(type==='textarea'?'<textarea rows="3" data-helper-key="'+key+'">'+esc(helperInput[key])+'</textarea>':'<input type="'+type+'" data-helper-key="'+key+'" value="'+esc(helperInput[key])+'" '+(type==='number'?'min="0"':'')+'>')+'</label>';let html='<details class="ns-business-helper" '+(open||helperOpen?'open':'')+'><summary>Help write my business brief from a website or About page</summary><p>Add your company website, known counts and what needs to change. We will prepare wording and options for you to review. Missing facts stay unknown.</p>'+field('url','Company website or About-page URL','url')+'<div class="ns-helper-counts">'+field('sites','Known sites','number')+field('users','Known users','number')+'</div>'+'<label>What are you comparing?<select data-helper-key="scope"><option value="">Not sure yet</option>'+[['sase','SASE'],['sdwan','SD-WAN'],['secure_access','SSE']].map(([v,n])=>'<option value="'+v+'" '+(helperInput.scope===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><fieldset><legend>Where do you need service? (optional)</legend>'+[['uk_ireland','UK / Ireland'],['europe','Europe'],['north_america','North America'],['asia_pacific','Asia Pacific'],['middle_east_africa','Middle East / Africa'],['latin_america','Latin America'],['china_mainland','Mainland China']].map(([v,n])=>'<label class="ns-helper-choice"><input type="checkbox" data-helper-region="'+v+'" '+(helperRegions.has(v)?'checked':'')+'>'+n+'</label>').join('')+'</fieldset>'+field('change','What needs to change?','textarea')+'<details class="ns-helper-extra" '+(helperExtraOpen?'open':'')+'><summary>Add known applications, cloud services or paste About text</summary>'+field('applications','Applications (separate with semicolons)')+field('cloud_services','Cloud services (separate with semicolons)')+field('existing_technology','Current network, security or identity platforms')+field('about','About your business','textarea')+'</details><p class="ns-paper-note">You can leave counts blank. Existing project facts are used when known. Website reading is limited to the public page you provide.</p><button type="button" data-helper-generate '+(helperBusy?'disabled':'')+'>'+(helperBusy?'Preparing your draft…':'Read website and prepare a draft')+'</button>'+(helperError?'<p class="ns-helper-error" role="alert">'+esc(helperError)+'</p>':'');
 if(helperDraft){html+='<div class="ns-helper-review"><h4>Review and edit before applying</h4><p>'+esc(helperDraft.warnings[0])+'</p><label>Editable business brief<textarea rows="7" data-helper-review>'+esc(helperDraft.description)+'</textarea></label><p>Select the proposed fields to use. Unselected fields keep their current values.</p>'+Object.entries(helperDraft.fields).map(([k,v])=>'<label class="ns-helper-choice"><input type="checkbox" data-helper-accept="'+k+'" '+(helperAccepted.has(k)?'checked':'')+'><span>'+esc(({sector:'Sector',scope:'Scope',sites:'Sites',users:'Users',regions:'Service regions',applications:'Applications',cloud_services:'Cloud services',existing_technology:'Existing technology'})[k]??k)+': '+esc(helperDisplay(k,v))+'</span></label>').join('')+'<label>Apply the reviewed wording<select data-helper-mode><option value="append" '+(helperMode==='append'?'selected':'')+'>Add to the current brief and keep existing wording</option><option value="replace" '+(helperMode==='replace'?'selected':'')+'>Replace the business brief with this reviewed wording</option></select></label><label class="ns-helper-choice"><input type="checkbox" data-helper-defaults '+(helperApplyDefaults?'checked':'')+'>Also include the recommended sector options</label>'+(helperDraft.source?'<details><summary>Company source: '+esc(helperDraft.source.url)+'</summary><a href="'+esc(helperDraft.source.url)+'" target="_blank" rel="noopener noreferrer">Open company page</a><p>'+esc(helperDraft.source.title)+'</p><pre class="ns-full-text">'+esc(helperDraft.source.text)+'</pre></details>':'')+'<button type="button" data-helper-apply>Apply reviewed brief to the RFP and map</button></div>';}
 return html+'</details>';}
 root.addEventListener('toggle',e=>{if(e.target.matches?.('.ns-business-helper'))helperOpen=e.target.open;if(e.target.matches?.('.ns-helper-extra'))helperExtraOpen=e.target.open;},true);
 root.addEventListener('input',e=>{const t=e.target;if(t.dataset.helperKey){helperInput[t.dataset.helperKey]=t.value;helperVersion++;helperDraft=null;helperError='';}if(t.hasAttribute('data-helper-review')&&helperDraft)helperDraft.description=t.value;});
 root.addEventListener('change',e=>{const t=e.target;if(t.dataset.helperRegion){if(t.checked)helperRegions.add(t.dataset.helperRegion);else helperRegions.delete(t.dataset.helperRegion);helperVersion++;helperDraft=null;}if(t.dataset.helperAccept){if(t.checked)helperAccepted.add(t.dataset.helperAccept);else helperAccepted.delete(t.dataset.helperAccept);}if(t.hasAttribute('data-helper-mode'))helperMode=t.value;if(t.hasAttribute('data-helper-defaults'))helperApplyDefaults=t.checked;});
 root.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-helper-generate')){if(helperBusy)return;helperBusy=true;helperOpen=true;helperError='';const version=helperVersion;renderLiving();renderNodeTask();try{const input={...helperInput,sites:Number(helperInput.sites)||state.sites||undefined,users:Number(helperInput.users)||state.users||undefined,sector:state.sector,scope:helperInput.scope||(state.confirmedFields.scope?state.scope:''),regions:helperRegions.size?[...helperRegions]:state.regions,existing_technology:helperInput.existing_technology||state.existing_technology,applications:helperInput.applications||state.applications.join('; '),cloud_services:helperInput.cloud_services||state.cloud_services.join('; ')};const res=await fetch('/api/context-preview/business-brief',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const data=await res.json();if(!res.ok)throw Error(data.error??'The business brief could not be prepared.');if(version!==helperVersion)throw Error('Your details changed while the draft was being prepared. Prepare it again using the updated details.');helperDraft=data;helperAccepted=new Set(Object.entries(data.fields).filter(([k,v])=>!state[k]||Array.isArray(state[k])&&!state[k].length||JSON.stringify(state[k])===JSON.stringify(v)||k==='scope'&&!state.confirmedFields.scope).map(([k])=>k));helperMode=state.business?'append':'replace';}catch(error){helperError=error.message;}finally{helperBusy=false;renderLiving();renderNodeTask();}}
 if(button.hasAttribute('data-helper-apply')){if(!helperDraft)return;const text=helperDraft.description.trim();const merged=helperMode==='replace'?text:[state.business,text].filter(Boolean).join('\n\n');if(merged.length>20000){helperError='The combined brief is over 20,000 characters. Edit it before applying. Your current project has not been changed.';renderLiving();renderNodeTask();return;}for(const key of helperAccepted){const value=helperDraft.fields[key];if(key==='sector'&&value!==state.sector){if(state.sector)state.selectionsBySector[state.sector]=[...state.selected];state.sector=value;state.selected=[...(state.selectionsBySector[value]??[])];}else state[key]=Array.isArray(value)?[...value]:value;if(key==='scope'){state.confirmedFields.scope=true;applyProductPreset(value);}}state.business=merged;for(const value of helperDraft.featureNeeds??[])if(!state.custom.some(c=>c.text===value))state.custom.push({id:'own'+Date.now().toString(36)+state.custom.length,text:value,kind:'custom',included:true,relatedTo:'project',relatedSector:state.sector,relation:'constrains'});if(helperApplyDefaults&&state.sector){state.defaults=true;defaults();addDefaultQuestions();}announceMapChange('Reviewed business brief applied. The document and provider comparison now use your accepted choices.');helperDraft=null;commit();}
 });
 let overviewDraft='',overviewSuggestions=null;
 let requirementsBasis=null,mapOverview=false,mapHomeGroup='project',lastPrimaryLayer=1;
 const mapHistory=createMapHistory('project');
 function reviewBasis(){return state.sector+':'+state.scope+':'+Boolean(state.confirmedFields.scope);}
 function markRequirementsReviewed(){state.confirmedFields.requirementsReviewed=true;requirementsBasis=reviewBasis();}
 function requirementsReviewed(){if(requirementsBasis&&requirementsBasis!==reviewBasis()){state.confirmedFields.requirementsReviewed=false;requirementsBasis=null;}return Boolean(state.confirmedFields.requirementsReviewed);}
 function recommendedPlan(){const plan=sectorStartingPlan(state.sector,state.confirmedFields.scope?state.scope:'',catalogue?.questions??[],challenges[state.sector]??[]);if(includedProducts().length)plan.questionIds=['Q-SM-01','Q-DP-01','Q-CM-01','Q-VE-03'].filter(id=>catalogue?.questions.some(q=>q.id===id));return plan;}
 function addDefaultQuestions(){documentSettings.questionIds=[...new Set([...documentSettings.questionIds,...recommendedPlan().questionIds])];state.confirmedFields.defaultQuestions=true;markRequirementsReviewed();}
 function applySectorDefaults(){if(!state.sector){openMapTask('sector');return;}state.defaults=true;defaults();addDefaultQuestions();announceMapChange('Sector plan applied: '+state.selected.length+' challenges and '+documentSettings.questionIds.length+' questions. Edit any choice in the map or Living RFP.');commit();}
 function announceMapChange(text){const el=$('#ns-map-change');if(el){el.textContent=text;el.hidden=false;}}
 function renderOverview(){let html=businessHelperMarkup(true)+'<p>Paste an About section or a project description. We will suggest the sector, scope, regions, counts and named applications we can identify. Review everything before applying.</p><label>About your company or project<textarea rows="7" id="ns-company-overview" placeholder="We are a manufacturer with 12 sites and 800 users in the UK and Europe. We need SASE, audit evidence and a phased migration. We use Microsoft 365 and Azure.">'+esc(overviewDraft)+'</textarea></label><button type="button" id="ns-parse-overview">Suggest options from this overview</button>';
 if(overviewSuggestions){const names={sector:'Sector',scope:'Solution scope',sites:'Sites',users:'Users',regions:'Service regions',applications:'Applications',cloud_services:'Cloud services'},pretty=(k,v)=>k==='sector'?(sectors.find(s=>s[0]===v)?.[1]??v):k==='scope'?{sase:'SASE',sdwan:'SD-WAN',secure_access:'SSE'}[v]:Array.isArray(v)?v.map(x=>({uk_ireland:'UK / Ireland',europe:'Europe',north_america:'North America',asia_pacific:'Asia Pacific',middle_east_africa:'Middle East / Africa',latin_america:'Latin America',china_mainland:'Mainland China'}[x]??x)).join(', '):v;
 html+='<section class="ns-overview-review"><h3>Review the suggested choices</h3>'+Object.entries(overviewSuggestions.fields).map(([k,v])=>'<label><input type="checkbox" data-overview-accept="'+k+'" checked><strong>'+names[k]+': '+esc(pretty(k,v))+'</strong><small>From your wording: “'+esc(overviewSuggestions.sources[k])+'”</small></label>').join('')+'<p>'+overviewSuggestions.featureNeeds.length+' feature-need statements will be retained as your own context, with supplier confirmation still required.</p>'+overviewSuggestions.warnings.map(t=>'<p class="ns-small">'+esc(t)+'</p>').join('')+'<p>Sector defaults also include a short editable set of core and sector questions on service responsibilities, deployment, pricing and sector references. The full original overview is retained in your business brief. Existing details you have already entered are kept unless you choose to replace a detected field.</p><button type="button" id="ns-apply-overview">Apply reviewed choices and sector defaults</button></section>';}
 return html;}
 root.addEventListener('input',e=>{if(e.target.id==='ns-company-overview')overviewDraft=e.target.value;});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(['ns-use-sector-defaults-global','ns-use-sector-defaults-node','ns-use-sector-defaults-sector','ns-use-defaults-living','ns-apply','ns-paper-defaults','ns-paper-defaults-requirements','ns-paper-defaults-questions'].includes(b.id)){e.preventDefault();e.stopImmediatePropagation();applySectorDefaults();return;}if(b.id==='ns-parse-overview'){if(!overviewDraft.trim())return;if(overviewDraft.length>20000){projectStatus('The overview is longer than the current 20,000-character brief limit. Your wording has not been shortened.');return;}overviewSuggestions=parseCompanyOverview(overviewDraft);renderNodeTask();return;}if(b.id==='ns-apply-overview'){const s=overviewSuggestions;if(!s)return;for(const el of $$('[data-overview-accept]:checked')){const k=el.dataset.overviewAccept,v=s.fields[k];if(k==='sector'&&v!==state.sector){if(state.sector)state.selectionsBySector[state.sector]=[...state.selected];state.sector=v;state.selected=[...(state.selectionsBySector[v]??[])];}else state[k]=Array.isArray(v)?[...v]:v;if(k==='scope'){state.confirmedFields.scope=true;applyProductPreset(v);}}
 state.business=s.original;for(const text of s.featureNeeds){if(!state.custom.some(c=>c.text===text))state.custom.push({id:'own'+Date.now().toString(36)+state.custom.length,text,kind:'custom',included:true,relatedTo:'project',relatedSector:state.sector,relation:'constrains'});}if(state.sector){state.defaults=true;defaults();addDefaultQuestions();}state.mapTask='project';state.focus='project';announceMapChange('Company overview applied. Review the highlighted choices, sector defaults and the missing items in your Living RFP.');commit();}
 },true);

 let livingSections=new Set(['scope','challenges']);let outreachIntent='rfp';let outreachOpen=false;
 function livingField(key,label,value,type='text'){return '<label>'+label+(type==='textarea'?'<textarea rows="3" data-living-field="'+key+'">'+esc(value)+'</textarea>':'<input type="'+type+'" data-living-field="'+key+'" value="'+esc(value)+'" '+(type==='number'?'min="0"':'')+'>')+'</label>';}
 function missingProjectItems(){const items=[];if(!state.sector)items.push({task:'sector',label:'Company sector',section:'scope'});if(!state.confirmedFields?.scope)items.push({task:'scope',label:'Products and services',section:'scope'});if(!(state.sites>0||state.users>0))items.push({task:'estate',label:'A site or user count',section:'scope'});if(!state.regions.length)items.push({task:'coverage',label:'Service regions',section:'scope'});if(state.business.trim().length<20)items.push({task:'business',label:'A short business requirement',section:'scope'});if(!documentSettings.timescale)items.push({task:'timing',label:'Buying timescale, including Not decided',section:'instructions'});if(state.doc==='rfp'&&!documentSettings.questionIds.length)items.push({task:'questions',label:'At least one supplier question',section:'questions'});return items;}
 function updateMissingItems(){const el=$('#ns-living-missing');if(!el)return;const missing=missingProjectItems();el.innerHTML='<div><strong>'+ (missing.length?missing.length+(missing.length===1?' thing still to add or review':' things still to add or review'):'The basic brief fields are complete')+'</strong><p>'+ (missing.length?'Your draft is being built. Select an item below to complete that section, or use the same choices on the map.':'Review the wording, evidence requests and recipient list before using this brief.')+'</p></div><div class="ns-missing-items">'+missing.map(i=>'<button type="button" data-living-missing="'+i.task+'" data-living-section="'+i.section+'">○ '+esc(i.label)+' →</button>').join('')+'</div>'+(state.sector?'<div class="ns-defaults-plan"><strong>'+esc(sectorName())+' starting plan</strong><p>'+state.selected.length+' challenges included. Your map changes are used here exactly as selected.</p><p>Defaults also add a short editable set of supplier questions about service responsibilities, deployment, pricing and comparable-sector references. Your existing choices are kept.</p><button type="button" id="ns-use-defaults-living" data-sector-defaults>Use recommended defaults for '+esc(sectorName().toLowerCase())+'</button></div>':'<button type="button" data-task="company-overview">Start with my company overview →</button>');}

 function renderLiving(){for(const d of $$('#ns-living-content details[id]')){const key=d.id.replace('ns-living-section-','');if(d.open)livingSections.add(key);else livingSections.delete(key);}const box=$('#ns-living-content');if(!box)return;if(box.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select')){updateLivingPreview();return;}
 const fields=livingField('business','What needs to change?',state.business,'textarea')+(requirementsReady()?'<button type="button" id="ns-use-starting-brief">Build a starting brief from my choices</button>':'')+'<div class="ns-living-counts">'+livingField('sites','Sites',state.sites||'','number')+livingField('users','Users',state.users||'','number')+'</div><div class="ns-sector-list">'+sectors.map(([id,n])=>'<button type="button" data-sector="'+id+'" aria-pressed="'+(state.sector===id)+'">'+esc(n)+'</button>').join('')+'</div><button type="button" data-task="scope">Edit products and features on the map ↗</button><fieldset><legend>Service regions</legend>'+[['uk_ireland','UK / Ireland'],['europe','Europe'],['north_america','North America'],['asia_pacific','Asia Pacific'],['middle_east_africa','Middle East / Africa'],['latin_america','Latin America'],['china_mainland','Mainland China']].map(([id,n])=>'<label><input type="checkbox" data-region="'+id+'" '+(state.regions.includes(id)?'checked':'')+'>'+n+'</label>').join('')+'</fieldset>';
 const challenges=(challengesForLiving()).map(([c,i])=>'<article class="ns-living-clause"><label><input type="checkbox" data-doc-context="'+i+'" '+(state.selected.includes(i)?'checked':'')+'>'+esc(c.title)+'</label><p>'+esc(c.test)+'</p><small>'+esc(originFor(i)==='suggested'?'Suggested from your sector. You can change it.':'Selected by you.')+'</small><label><input type="checkbox" data-doc-mandatory="c'+i+'" '+(weight('c'+i)===3?'checked':'')+'>Must-have</label></article>').join('')+state.custom.map(c=>'<article class="ns-living-clause"><label><input type="checkbox" data-doc-custom="'+c.id+'" '+(c.included!==false?'checked':'')+'>Your own requirement</label><textarea rows="3" data-custom-text="'+c.id+'">'+esc(c.text)+'</textarea><label><input type="checkbox" data-doc-mandatory="'+c.id+'" '+(weight(c.id)===3?'checked':'')+'>Must-have</label></article>').join('')+'<label>Add your own requirement<textarea id="ns-living-own" rows="3" placeholder="A constraint or question specific to your business"></textarea></label><button type="button" id="ns-living-add-own">Add this requirement +</button>';
 const apps=livingField('applications','Applications, separated with semicolons',state.applications.join('; '),'textarea')+livingField('cloud_services','Cloud services, separated with semicolons',state.cloud_services.join('; '),'textarea')+livingField('existing_technology','Existing network and security technology',state.existing_technology,'textarea');
 const questions='<p>'+(state.doc==='rfi'?'Your RFI keeps a simple brief. These question choices are retained for a detailed RFP. Switch to RFP to include the question schedule. ':'')+'Select the questions suppliers should answer. All '+(catalogue?.questions.length??0)+' existing core and sector questions remain available.</p><input id="ns-living-question-filter" type="search" placeholder="Find a supplier question" aria-label="Find a question in the living RFP">'+(catalogue?.questions??[]).map(q=>'<label class="ns-living-bank" data-living-question-search="'+esc((q.category+' '+q.text).toLowerCase())+'"><input type="checkbox" data-bank-question="'+q.id+'" '+(documentSettings.questionIds.includes(q.id)?'checked':'')+'>'+esc(q.text)+'<small>'+esc(q.category)+' · '+esc(q.id)+'</small></label>').join('');
 const instructions='<label>Buying timescale<select data-living-timescale><option value="">Choose when known</option>'+['Within 3 months','3–6 months','6–12 months','Not decided'].map(t=>'<option value="'+t+'" '+(documentSettings.timescale===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Response format, commercial assumptions and other instructions<textarea rows="4" data-living-notes>'+esc(documentSettings.notes)+'</textarea></label>';
 const section=(id,title,html)=>'<details id="ns-living-section-'+id+'" '+(livingSections.has(id)?'open':'')+'><summary>'+title+'</summary>'+html+'</details>';
 box.innerHTML='<div class="ns-living-editor">'+section('scope','01 / Your business and scope',fields)+section('products','Products, buying actions and features',productsMarkup())+section('challenges','02 / Requirements and sector challenges',state.sector?challenges:'Choose a sector to see its typical challenges. You can add your own requirements too.')+section('applications','03 / Applications, cloud and current technology',apps)+section('questions','04 / Supplier response questions',questions)+section('instructions','05 / Procurement instructions',instructions)+'</div><div class="ns-living-document"><div class="ns-living-document-head"><div><span class="ns-kicker">Generated from your project</span><h3 id="ns-living-title">Your '+state.doc.toUpperCase()+' draft</h3></div><div class="ns-segment"><button type="button" data-doc="rfi" aria-pressed="'+(state.doc==='rfi')+'">RFI</button><button type="button" data-doc="rfp" aria-pressed="'+(state.doc==='rfp')+'">RFP</button></div></div><p>Edit directly on the document below, use the section controls, or work in the map. All three update the same project.</p><p id="ns-paper-sync" role="status" class="ns-paper-sync">Ready to edit. Changes stay in this local project.</p><div class="ns-node-downloads"><button type="button" data-project-export="docx">Download Word ↓</button><button type="button" data-project-export="markdown">Download text ↓</button></div><label><input type="checkbox" id="ns-living-attach-research">Include complete research for the selected providers</label><div class="ns-word-view-label"><span>Editable document</span><span>A4 · System font</span></div><div class="ns-word-workspace"><article id="ns-living-preview" class="ns-written-document" aria-label="Living procurement document"></article></div><section id="ns-living-checks"></section></div>';
 updateLivingPreview();}
 function challengesForLiving(){return (challenges[state.sector]??[]).map((c,i)=>[c,i]);}
 function documentMarkup(markdown){
  // Render source text as document structure. Research and buyer wording stay escaped and complete.
  const inline=text=>esc(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  return markdown.split(/\n\s*\n/).map(block=>{const heading=block.match(/^(#{1,6}) ([^\n]+)$/);if(heading){const level=Math.min(6,heading[1].length+1);return '<h'+level+'>'+inline(heading[2])+'</h'+level+'>';}
   const lines=block.split('\n');if(lines.every(line=>/^[-*] /.test(line)))return '<ul>'+lines.map(line=>'<li>'+inline(line.slice(2))+'</li>').join('')+'</ul>';
   if(lines.every(line=>/^\d+[.)] /.test(line)))return '<ol>'+lines.map(line=>'<li>'+inline(line.replace(/^\d+[.)] /,''))+'</li>').join('')+'</ol>';
   return '<p>'+lines.map(inline).join('<br>')+'</p>';
  }).join('');
 }
 let paperOwnDraft='';
 function paperText(key,label,value,custom=false){return '<textarea rows="1" class="ns-paper-text" '+(custom?'data-custom-text="'+esc(key)+'"':'data-living-field="'+key+'"')+' aria-label="'+esc(label)+'" placeholder="'+esc(label)+'">'+esc(value)+'</textarea>';}
 function paperSelect(key,label,value,options){return '<label class="ns-paper-field"><span>'+label+'</span><select data-paper-select="'+key+'" aria-label="'+label+'">'+options.map(([v,n])=>'<option value="'+v+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label>';}
 function paperRequirements(){const definitions=challenges[state.sector]??[];return definitions.map((c,i)=>'<section class="ns-paper-requirement"><label class="ns-paper-check"><input type="checkbox" data-doc-context="'+i+'" '+(state.selected.includes(i)?'checked':'')+'>'+esc(c.title)+'</label><p>'+esc(c.test)+'</p><label class="ns-paper-check ns-paper-note"><input type="checkbox" data-doc-mandatory="c'+i+'" '+(weight('c'+i)===3?'checked':'')+'>Must-have</label><small class="ns-paper-note">Sector research. Original wording retained.</small></section>').join('')+state.custom.map(c=>'<section class="ns-paper-requirement"><label class="ns-paper-check"><input type="checkbox" data-doc-custom="'+c.id+'" '+(c.included!==false?'checked':'')+'>Your requirement</label>'+paperText(c.id,'Edit your requirement',c.text,true)+'<label class="ns-paper-check ns-paper-note"><input type="checkbox" data-doc-mandatory="'+c.id+'" '+(weight(c.id)===3?'checked':'')+'>Must-have</label></section>').join('')+'<section class="ns-paper-add"><label for="ns-paper-own">Add a requirement in your own words</label><textarea class="ns-paper-text" rows="2" id="ns-paper-own" placeholder="Describe a requirement or supplier question">'+esc(paperOwnDraft)+'</textarea><button type="button" id="ns-paper-add-own">Add to this RFP and map +</button></section>';}
 function editablePaper(){const scope={sase:'SASE',sdwan:'SD-WAN',secure_access:'SSE'}[state.scope],questions=catalogue?.questions??[];
 const basics='<div class="ns-paper-fields">'+'<p class="ns-paper-note">Products selected: '+esc(productSummary()||'None selected')+'. Edit the product schedule below.</p>'+'<div class="ns-paper-counts">'+['sites','users'].map(k=>'<label class="ns-paper-field"><span>'+ (k==='sites'?'Sites':'Users')+'</span><input type="number" min="0" max="'+(k==='sites'?100000:1000000)+'" data-living-field="'+k+'" value="'+(state[k]||'')+'" placeholder="Not known" aria-label="Document '+k+'"></label>').join('')+'</div><fieldset class="ns-paper-regions"><legend>Service regions</legend>'+[['uk_ireland','UK / Ireland'],['europe','Europe'],['north_america','North America'],['asia_pacific','Asia Pacific'],['middle_east_africa','Middle East / Africa'],['latin_america','Latin America'],['china_mainland','Mainland China']].map(([id,n])=>'<label><input type="checkbox" data-region="'+id+'" '+(state.regions.includes(id)?'checked':'')+'>'+n+'</label>').join('')+'</fieldset>'+paperSelect('ownership','Service ownership',state.ownership,[[3,'Not decided'],[0,'Our team'],[1,'Co-managed'],[2,'Provider operates it']])+paperSelect('timescale','Buying timescale',documentSettings.timescale,[['','Not stated'],...['Within 3 months','3–6 months','6–12 months','Not decided'].map(t=>[t,t])])+'</div>';
 const section=(title,body)=>'<h3>'+title+'</h3>'+body;
 const selectedQuestions=questions.filter(q=>documentSettings.questionIds.includes(q.id));
 const questionHtml=(state.doc==='rfi'?'<p class="ns-paper-note">Question selections are kept for your detailed RFP. The RFI export omits this schedule.</p>':'')+selectedQuestions.map(q=>'<label class="ns-paper-check ns-paper-question"><input type="checkbox" data-bank-question="'+q.id+'" checked><span>'+esc(q.text)+'<small>'+esc(q.id)+'</small></span></label>').join('')+'<details class="ns-paper-options"><summary>Add supplier questions ('+questions.length+' available)</summary><input type="search" id="ns-paper-question-filter" placeholder="Find a supplier question" aria-label="Find supplier questions in document">'+questions.map(q=>'<label class="ns-paper-check ns-paper-question" data-paper-question-search="'+esc((q.category+' '+q.text).toLowerCase())+'"><input type="checkbox" data-bank-question="'+q.id+'" '+(documentSettings.questionIds.includes(q.id)?'checked':'')+'><span>'+esc(q.text)+'<small>'+esc(q.category)+' · '+q.id+'</small></span></label>').join('')+'</details>';
 // The editable fields write to the same project. Generated source material remains complete below them.
 let html='<p class="ns-paper-note">Private working draft · Edit directly on this page</p><h2>'+(state.confirmedFields.scope?'Network and security '+state.doc.toUpperCase():state.doc==='rfi'?'Request for information':'Request for proposal')+'</h2>';
 html+=section('Statement of requirements',businessHelperMarkup()+paperText('business','Describe your business and what needs to change',state.business));html+=section('Project scope',basics);
 html+=section('Products, buying actions and features',productsMarkup());
 html+=section('Sector and operating context',paperSelect('sector','Company sector',state.sector,[['','Choose your sector'],...sectors])+'<button type="button" id="ns-paper-defaults" data-sector-defaults>Use sector defaults</button>');
 html+=section('Applications and cloud services','<label class="ns-paper-field"><span>Applications (separate with semicolons)</span>'+paperText('applications','Application names',state.applications.join('; '))+'</label><label class="ns-paper-field"><span>Cloud services (separate with semicolons)</span>'+paperText('cloud_services','Cloud service names',state.cloud_services.join('; '))+'</label>');
 html+=section('Existing technology',paperText('existing_technology','Existing network and security technology',state.existing_technology));
 html+=section('Requirements and supplier evidence requests',recommendedControls('requirements')+paperRequirements()+(projectView?.requirements??[]).filter(r=>!r.id.startsWith('buyer:')&&!r.id.startsWith(state.sector+':')).map(r=>'<h4>'+esc(r.text)+'</h4><p>'+esc(r.test)+'</p><p class="ns-paper-note">'+esc(r.id)+' · Supplier confirmation required.</p>').join(''));
 html+=section('Supplier response questions',recommendedControls('questions')+questionHtml);if(sourceDocumentSection('Requested response'))html+=section('Requested response',documentMarkup(sourceDocumentSection('Requested response')));
 html+=section('Additional procurement instructions','<textarea rows="2" class="ns-paper-text" data-living-notes aria-label="Document procurement instructions" placeholder="Response format, dates, commercial assumptions or other instructions">'+esc(documentSettings.notes)+'</textarea>');
 if(projectView){html+='<details class="ns-paper-generated"><summary>Complete generated procurement wording</summary>'+documentMarkup(projectView.markdown)+'</details>';}
 html+=section('Document control','<div class="ns-paper-note">'+(sourceDocumentSection('Document control')?documentMarkup(sourceDocumentSection('Document control')):'<p>Private local draft. Your edits update the shared project. Nothing has been published or issued to suppliers.</p>')+'</div>');return html;
 }
 function sizePaperText(){for(const t of $$('#ns-living-preview textarea')){t.style.height='auto';t.style.height=Math.max(42,t.scrollHeight+2)+'px';}}
 function syncSharedDocumentFields(){for(const t of $$('[data-living-field]')){if(t===document.activeElement)continue;const k=t.dataset.livingField,value=Array.isArray(state[k])?state[k].join('; '):['sites','users'].includes(k)?state[k]||'':state[k];if(t.value!==String(value))t.value=value;}for(const t of $$('[data-custom-text]')){if(t!==document.activeElement){const c=state.custom.find(c=>c.id===t.dataset.customText);if(c&&t.value!==c.text)t.value=c.text;}}for(const t of $$('[data-living-notes]'))if(t!==document.activeElement)t.value=documentSettings.notes;}
 function sourceDocumentSection(title){if(!projectView)return '';const chunks=projectView.markdown.split(/^## /m);const section=chunks.find(c=>c.split('\n',1)[0]===title);return section?section.slice(section.indexOf('\n')+1).trim():'';}
 function updateLivingPreview(){syncSharedDocumentFields();updateMissingItems();const el=$('#ns-living-preview');if(!el)return;const title=$('#ns-living-title');if(title)title.textContent='Your '+state.doc.toUpperCase()+' draft';
 const editing=el.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select');
 if(!editing){const scroll=$('.ns-word-workspace')?.scrollTop??0;el.innerHTML=editablePaper();sizePaperText();if($('.ns-word-workspace'))$('.ns-word-workspace').scrollTop=scroll;}
 const sync=$('#ns-paper-sync');if(sync)sync.textContent=projectError?'Please review: '+projectError:liveError?'Comparison: '+liveError:projectPending||liveBusy?'Updating document and provider evidence…':providerRecommendationsReady()?'Edits are in sync with the map and provider comparison.':locationWorkspace?'Your Living RFP is in sync. Next: '+locationWorkspace.readiness().label+'. Provider recommendations wait for site and user review.':'Add sector, scope, one known count and service regions to begin.';
 const checks=$('#ns-living-checks');if(checks)checks.innerHTML=projectView?.readiness.length?'<h3>Still to review</h3><ul>'+projectView.readiness.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':'<p>Private working draft. Nothing has been issued to suppliers.</p>';$$('[data-project-export]').forEach(b=>b.disabled=!projectView||projectPending||!requirementsReady());renderOutreach();locationWorkspace?.renderDocument();}
 root.addEventListener('change',e=>{const t=e.target;if(!t.dataset.paperSelect)return;const k=t.dataset.paperSelect,v=t.value;
 if(k==='sector'){if(state.sector)state.selectionsBySector[state.sector]=[...state.selected];state.sector=v;state.selected=[...(state.selectionsBySector[v]??[])];state.defaults=false;announceMapChange(v?'Sector changed in the Living RFP. Review the suggested challenges for '+sectorName()+'. Your earlier sector choices are retained.':'Choose a sector to compare providers.');}
 else if(k==='scope'){if(v)applyProductPreset(v);}
 else if(k==='ownership'){state.ownership=Number(v);state.confirmedFields.operating=true;}
 else if(k==='timescale')documentSettings.timescale=v;
 t.blur();commit();});
 root.addEventListener('input',e=>{const t=e.target;if(t.id==='ns-paper-question-filter'){const term=t.value.toLowerCase();$$('[data-paper-question-search]').forEach(row=>row.hidden=!row.dataset.paperQuestionSearch.includes(term));return;}if(t.id==='ns-paper-own')paperOwnDraft=t.value;if(t.closest('#ns-living-preview')){if(t.tagName==='TEXTAREA'){t.style.height='auto';t.style.height=Math.max(42,t.scrollHeight+2)+'px';}updateJourney();}});
