 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='ns-paper-defaults'){applySectorDefaults();return;}if(b.id==='ns-paper-add-own'){const text=$('#ns-paper-own').value;if(!text.trim())return;paperOwnDraft='';state.custom.push({id:'own'+Date.now().toString(36)+state.custom.length,text,kind:'custom',included:true,relatedTo:'project',relatedSector:state.sector,relation:'constrains'});commit();}});
 function renderOutreach(){const box=$('#ns-outreach-preview');if(!box)return;if(box.contains(document.activeElement)&&document.activeElement.matches('input'))return;box.hidden=!outreachOpen;if(!outreachOpen)return;const names=selectedProviders.map(slug=>liveResult?.providers.find(p=>p.slug===slug)?.name??knowledge?.provider_records.find(p=>p.provider.slug===slug)?.provider.display_name??slug);const labels={contact:'Request contact',demo:'Request a demonstration',pricing:'Ask for indicative pricing',rfp:'Request RFI / RFP responses',publish:'Review your opportunity before publication'};box.innerHTML='<button type="button" data-open-room="">Prepare project conversations ↗</button><span class="ns-kicker">Request preview only</span><h3>'+labels[outreachIntent]+'</h3>'+(outreachIntent==='publish'?'<section class="ns-local-review"><h4>Anonymous opportunity preview</h4>'+(projectView&&!projectPending&&requirementsReady()?'<p><strong>'+esc(projectView.publicNotice.title)+'</strong></p><p>'+esc(projectView.publicNotice.size)+' · '+esc(projectView.publicNotice.regions)+'</p><p>'+esc(projectView.publicNotice.summary)+'</p>':'<p>Add your sector, products, a known site or user count and service regions to build the opportunity preview.</p>')+'<p>Your full brief stays separate. Review identifying details and decide which suppliers may receive it. Publication is unavailable in this preview.</p><button type="button" data-task="written-brief">Review the brief on the map ↗</button></section>':'')+(outreachIntent==='pricing'?'<section class="ns-local-review"><h4>Your pricing scope</h4><p>'+esc(sectors.find(s=>s[0]===state.sector)?.[1]||'Sector not supplied')+' · '+(state.sites?esc(state.sites)+' sites':'Sites not known')+' · '+(state.users?esc(state.users)+' users':'Users not known')+'</p><p>'+esc(helperDisplay('regions',state.regions))+'</p><p>'+esc(state.products.filter(p=>p.included).map(p=>productDefinitions().find(d=>d.id===p.id)?.label||p.id).join('; '))+'</p><p>'+esc(state.business||'Business background still to add.')+'</p></section>':'')+'<p><strong>Providers:</strong> '+(names.length?names.map(esc).join(', '):'Choose providers in your comparison first.')+'</p><p>The proposed journey is: prepare privately, verify the email where replies should go, review the exact brief and recipients, then approve sending. No password or account setup while drafting.</p><ol><li>Review your scope and selected requirements.</li><li>Choose which providers receive this request.</li><li>Verify your reply address with a one-time code.</li><li>Approve the exact request before it is sent.</li></ol><p>'+(outreachIntent==='pricing'?'Ask suppliers to state whether pricing is indicative, what it includes, contract duration, licences and assumptions. No price has been generated here.':'The same requirements will be attached so suppliers can respond against your actual project.')+'</p><label>Your reply email in the proposed flow<input type="email" autocomplete="off" placeholder="you@company.com" aria-label="Reply email preview"></label><p class="ns-small">Local mockup. This email is not saved or sent. Supplier routing, verification and sending are not connected.</p><button type="button" disabled>Verification and sending unavailable in preview</button>';}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.livingSection){livingSections.add(b.dataset.livingSection);for(const d of $$('#ns-living-content details[id]'))if(d.id==='ns-living-section-'+b.dataset.livingSection)d.open=true;renderLiving();$('#ns-living-section-'+b.dataset.livingSection)?.scrollIntoView({behavior:'smooth',block:'center'});}else if(b.id==='ns-living-add-own'){const text=$('#ns-living-own').value;if(!text.trim())return;state.custom.push({id:'own'+Date.now().toString(36)+state.custom.length,text,kind:'custom',included:true,relatedTo:'project',relatedSector:state.sector,relation:'constrains'});commit();}else if(b.dataset.outreachIntent){outreachIntent=b.dataset.outreachIntent;outreachOpen=true;renderOutreach();}});
 root.addEventListener('input',e=>{const t=e.target;if(t.id==='ns-living-question-filter'){const value=t.value.toLowerCase();$$('[data-living-question-search]').forEach(l=>l.hidden=!l.dataset.livingQuestionSearch.includes(value));return;}if(t.dataset.livingField){const k=t.dataset.livingField;state[k]=['sites','users'].includes(k)?Number(t.value):['applications','cloud_services'].includes(k)?t.value.split(';').map(v=>v.trim()).filter(Boolean):t.value;if(['sites','users'].includes(k))locationWorkspace?.refresh();syncProject();scheduleComparison();draw();}else if(t.hasAttribute('data-living-notes')){documentSettings.notes=t.value;syncProject();}});
