root.addEventListener('click',e=>{const tools=$('.ns-workspace-tools');if(tools.open&&(!tools.contains(e.target)||e.target.closest('[data-task],[data-map-level],#ns-map-overview,#ns-toggle-controls,#ns-load-device,[data-sector-defaults]')))tools.open=false;if(e.target.closest('#ns-map-overview')){e.stopImmediatePropagation();mapOverview=true;state.mapTask=null;state.focus=null;render();return;}if(e.target.closest('#ns-toggle-controls')){root.dataset.controls=String(root.dataset.controls!=='true');$('#ns-toggle-controls').setAttribute('aria-expanded',root.dataset.controls);return;}if(orbit?.shouldSuppressClick()&&e.target.closest('#ns-nodes,canvas')){e.preventDefault();e.stopImmediatePropagation();return;}const b=e.target.closest('button,a');if(!b)return;if(b.id==='ns-recommend-continue'||b.id==='ns-requirements-continue'){e.preventDefault();e.stopImmediatePropagation();if(b.id==='ns-recommend-continue')applySectorDefaults();markRequirementsReviewed();openMapTask(requirementsReady()?'project-shortlist':nextMapStep());return;}if(b.hasAttribute('data-save-continue')){e.preventDefault();e.stopImmediatePropagation();const task=state.mapTask;saveWorkingProject().then(ok=>{if(!ok||state.mapTask!==task)return;const next=nextMapStep();if(next==='written-brief'&&state.mapTask==='written-brief'){$('#ns-living-rfp').scrollIntoView({behavior:'smooth',block:'start'});return;}openMapTask(next);focusMapLevel(true);});return;}if(b.hasAttribute('data-next-card')){e.preventDefault();e.stopImmediatePropagation();const next=nextMapStep();if(next==='written-brief'&&state.mapTask==='written-brief'){$('#ns-living-rfp').scrollIntoView({behavior:'smooth',block:'start'});return;}openMapTask(next);focusMapLevel(true);if(['estate','business','document-business','timing'].includes(next))$('#ns-node-editor input, #ns-node-editor textarea, #ns-node-editor select')?.focus({preventScroll:true});return;}let task=b.dataset.task??b.dataset.mapLevel??null;if(b.dataset.scope)state.confirmedFields.scope=true;
 if(b.id==='ns-close-node'){e.stopImmediatePropagation();state.mapTask=null;state.focus=null;render();return;}
 if(b.dataset.node){const n=b.dataset.node;if(/^c\d+$/.test(n)||state.custom.some(c=>c.id===n)){e.stopImmediatePropagation();state.mapTask=null;state.focus=n;render();return;}task=n.startsWith('provider:')?n:n;}
 if(b.dataset.provider)task='provider:'+b.dataset.provider;
 if(b.dataset.readProvider){if(!liveResult){state.fullProvider=b.dataset.readProvider;state.researchOpen=true;renderReader();$('#ns-live-evidence').scrollIntoView({behavior:'smooth',block:'start'});e.stopImmediatePropagation();return;}task='provider:'+b.dataset.readProvider;}
 if(b.id==='ns-edit-brief'||b.dataset.phase==='context')task='project';
 if(b.id==='ns-open-all'&&!liveResult){state.allProviders=!state.allProviders;renderAllProviders();if(state.allProviders)$('#ns-all-providers').scrollIntoView({behavior:'smooth',block:'start'});e.stopImmediatePropagation();return;}if(b.id==='ns-open-all'||b.id==='ns-compare-selected'||b.dataset.phase==='evidence')task='project-shortlist';
 if(b.id==='ns-next')task=nextMapStep();if(b.id==='ns-rfp-promo'||b.dataset.phase==='draft')task='written-brief';if(b.id==='ns-use-starting-brief'){e.stopImmediatePropagation();addStartingBrief();return;}
 if(b.id==='ns-node-add-custom'){e.stopImmediatePropagation();const text=$('#ns-node-custom').value;if(!text.trim())return;state.custom.push({id:'own'+Date.now().toString(36)+state.custom.length,text,kind:'custom',included:true,relatedTo:'project',relatedSector:state.sector,relation:'constrains'});state.mapTask=null;state.focus=state.custom.at(-1).id;commit();return;}
 if(b.dataset.nodeOwnership!==undefined){e.stopImmediatePropagation();state.ownership=Number(b.dataset.nodeOwnership);state.confirmedFields.operating=true;commit();return;}
 if(task){e.preventDefault();e.stopImmediatePropagation();openMapTask(task);}
},true);
root.addEventListener('change',e=>{if(e.target.id==='ns-node-defaults'){state.defaults=e.target.checked;if(state.defaults)defaults();commit();}});
root.addEventListener('input',e=>{const key=e.target.dataset.nodeField;if(!key)return;const v=e.target.value;state[key]=['sites','users'].includes(key)?Number(v):['applications','cloud_services'].includes(key)?v.split(';').map(s=>s.trim()).filter(Boolean):v;state.started=validBrief();syncProject();scheduleComparison();draw();updateJourney();});
