root.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.id==='ns-save-device'){await saveWorkingProject();return;}if(b.id==='ns-save-brief'){if(!validBrief()){projectStatus('Complete the starting brief before saving this project.');return;}if(projectPending||!projectView){projectStatus(projectError||'Wait for the current project to validate before saving. Your fields remain intact.');return;}const data=JSON.stringify(packet(),null,2);if(b.id==='ns-save-device'){localStorage.setItem(LOCAL_KEY,data);$('#ns-load-device').hidden=false;projectStatus('Project saved on this device. Use Download project for a portable backup.');}else{downloadBlob(new Blob([data],{type:'application/json'}),'netify-context-project.json');projectStatus('Project backup downloaded, including unselected contexts and question choices.');}}
 else if(b.id==='ns-reopen')$('#ns-import-project').click();
 else if(b.id==='ns-load-device'){const saved=localStorage.getItem(LOCAL_KEY);if(!saved)throw Error('No saved project on this device.');await restorePacket(JSON.parse(saved));}
 else if(b.dataset.projectExport)await exportProject(b.dataset.projectExport,Boolean(b.closest('#ns-living-rfp')));
 else if(b.dataset.mapContext){state.phase='context';state.briefOpen=false;state.researchOpen=false;state.fullProvider=null;state.allProviders=false;state.focus=b.dataset.mapContext;render();}
 else if(b.id==='ns-document-edit-brief'){state.briefOpen=true;state.phase='context';state.researchOpen=false;state.allProviders=false;state.fullProvider=null;render();}
 else if(b.id==='ns-document-back'){state.phase='context';render();}
 else if(b.id==='ns-document-add-context'){state.phase='context';render();$('#ns-context').focus();}
 else if(b.id==='ns-rfp-promo'){e.preventDefault();state.phase='draft';state.briefOpen=false;state.researchOpen=false;state.fullProvider=null;state.allProviders=false;render();$('#netify-space').scrollIntoView({behavior:'smooth'});}
 else if(b.dataset.toggleProvider){const id=b.dataset.toggleProvider;selectedProviders=selectedProviders.includes(id)?selectedProviders.filter(s=>s!==id):[...selectedProviders,id];render();}
 }catch(err){projectStatus(err.message);}});
