 if(!allowed(payload,['version','projectId','basis','requirements','proposal'])||payload.version!=='netify-supplier-response/1'||payload.projectId!==core.project.id||payload.basis!==await projectBasisDigest(core))throw Error('This response belongs to a different brief. Keep the original response and open its matching buying plan, or request a revision.');
